import { logger, task } from "@trigger.dev/sdk/v3";

export const helloWorld = task({
  id: "hello-world",
  run: async (payload: { name?: string }) => {
    const name = payload.name ?? "World";

    logger.info("Hello from Trigger.dev", { name });

    return {
      message: `Hello, ${name}!`,
    };
  },
});
